    inline uintptr_t cUI_Popup_setText{};               // ENG 006E6EA0; thiscall (?, const wstring*, bool)
    inline uintptr_t cUI_Popup_setTextId{};             // ENG 006E6FB0; thiscall (?, text id, bool)
