    // cEngine
    inline uintptr_t cEngine_renderThreadRun{};         // ENG 0060E350; fastcall (engine), loops until shutdown
    // Frame limiter: cdecl (double, uint16 fps); spins with Sleep(0) until 1/fps passed since its last return.
    // The render loop calls it with 60 before each flip (skipped if 0x182EE3C has 0x4000), the menu loop too.
    inline uintptr_t frameLimiter{};                    // ENG 0060A9F0
    inline uintptr_t renderLimiterReturn{};             // ENG 0060EA6E
    // cEngine_updateWorldCursor (0x611E70) asks the UI whether the cursor is over a window before picking.
    inline uintptr_t worldCursorUiTestCall{};           // ENG 00611EE3
    inline uintptr_t captureLockBackReturn{};           // ENG 006136AB; after captureInternal's call to lockBack
    // Screenshots: dxDriver7_startCapture (ENG 00648660, thiscall (frames)) sets dxDriver7 +0xA8 (frames left) and
    // +0xAC (frames taken); every caller (Print Screen, the game's screenshot key, a debug key) asks for one frame.
    // While +0xA8 is set, dxDriver7_flip locks the back buffer and calls captureScreenshot: mode -1 = one screenshot,
    // written by writeTga1024x768 (ENG 006482C0) as .\Capture\shotNNNN.tga, which a thread (ENG 00648430) converts to a
    // quality 50 JPEG through IJL. Both assume 1024x768 (the 32-bit path ignores the pitch). Modes >= 0 copy 3 MB
    // frames into a mapped file ("vidobj"), < -1 write them out as cap%04d.tga: only reached with more than one frame.
    inline uintptr_t captureScreenshot{};               // ENG 006487D0; cdecl (bits, pitch, mode)

    // World <-> pixel conversion (cdecl (out, point, rotation, projection) -> out). Pixels assume a projection
    // spanning 1024x768 pixels: true for g_unzoomedProjection, not for the device projection (W x H).
    inline uintptr_t pixelsToWorld{};                   // ENG 00623940
    inline uintptr_t worldToPixels{};                   // ENG 00623B60
    inline uintptr_t g_unzoomedProjection{};            // ENG 0182ED70

    // Ground: renderTileRow draws each tile's base through the quad batcher (cWorldView + 0x86890) and collects
    // tiles with blend layers into a fixed array (at most 0x6D5 per frame); after all rows cWorldView0_render
    // flushes the batcher and cWorldView_drawTileLayers draws the collected layers.
    inline uintptr_t cWorldView_renderTileRow{};        // ENG 0062AE90; thiscall (device, rowPos, detail)
    inline uintptr_t cWorldView_drawTileLayers{};       // ENG 0062D3C0; thiscall (device)
    inline uintptr_t cQuadBatcher_flush{};              // ENG 00629340; thiscall (device)
    // Draws the collected water/lava tiles (glow pass, then the tiles) and sets the water ambience from their
    // count and average position.
    inline uintptr_t cWorldView_drawWaterTiles{};       // ENG 0062DD00; thiscall (device)
    // Row walk: initRowWalk sets the even and odd row positions (WorldView::rowEven/rowOdd) from the view's top-left
    // corner; cWorldView0_render then calls renderTileRow for each and steps it one tile row down (tile + 0x41,
    // y + 48), changing sector at sector edges. The camera position (view coordinates) is set by the same frame.
    inline uintptr_t cWorldView_initRowWalk{};          // ENG 006328C0; thiscall (pos: +4 x, +8 y; map data)
    inline uintptr_t g_viewCameraX{};                   // ENG 00AD7998; int32
    inline uintptr_t g_viewCameraY{};                   // ENG 00AD799C; int32

