    inline uintptr_t cEngine_worldMouse{};              // ENG 006172C0; thiscall (event, flag) -> bool
    inline uintptr_t cEventMouseDown_vtable{};          // ENG 0089704C; x at +8, y at +0xC
    inline uintptr_t cEventMouseUp_vtable{};            // ENG 00899248
    // World-side cursor reads, redirected to physical coordinates: calls to cMouse::getX (ENG 00655850),
    // cMouse::getY (00655860) and cMouse_instance.
    inline uintptr_t worldGetXCalls[6]{};               // ENG 00611F54 00611F9D 0061273C 006127C8 00617DFC 00617E69
    inline uintptr_t worldGetYCalls[6]{};               // ENG 00611F47 00611F90 0061274D 006127D9 00617E0D 00617E5C
    inline uintptr_t worldMouseReads[5]{};              // ENG 004FB881 0060F268 006104C7 00611EC3 0062764E

    // Record caches of the map data object (constructor 0x6335F0, clear 0x633E80): thiscall (id) -> record, 0 if
    // id is 0. Each looks the id up in its own std::map<uint32_t, record> (find 0x640410: thiscall (&key) on the
    // map, returns the node or the head as end; node +0x10 key, +0x14 record), stamps the node with the current
    // time (0xCD7A50) on a hit, and on a miss reads the record from a data file, inserts it and may evict the node
    // with the oldest stamp. 0x635FE0 holds the ground layer records (16 bytes, map at +0xDE5C, stamp node +0x24),
    // 0x635E50 the 64-byte records also used by game logic (map at +0xDE50, stamp node +0x54).
    inline uintptr_t layerRecordCache{};                // ENG 00635FE0
    inline uintptr_t recordCache{};                     // ENG 00635E50
    inline uintptr_t recordMapFind{};                   // ENG 00640410
    inline uintptr_t g_recordStamp{};                   // ENG 00CD7A50

    // Game client (cGCclass, one instance). cGCclass_initNetwork (0x7D2BD0) binds a UDP socket (SO_REUSEADDR) to
    // NETWORK_PORT_LISTEN for the LAN list; cGCclass_pollLanGames (0x7D35F0) reads the gameservers' announcements
    // from it with select/__WSAFDIsSet/recvfrom (their only use in the exe) and drops games that were silent for
    // 5 s. cGCclass_joinLanGame (0x7D3D00) connects to the address inside the announcement.
    inline uintptr_t g_pGameClient{};                   // ENG 0182EBF0
    constexpr uintptr_t gameClient_lanSocket = 0x14;
    // cGCclass_initNetwork sets TinCat's drv_disable_nagle (TCP_NODELAY on the game connection) to
    // "data flow == LAN" (cGCclass + 0x40414 == 2): `cmp ebx, 2; sete al` after `xor eax, eax`.
    inline uintptr_t initNetworkNagleTest{};            // ENG 007D310E

    // cWorldView0 vtable slot 5: draws the isometric world (arg: device).
    inline uintptr_t cWorldView0_render{};              // ENG 00632140

    // cUI_Manager::render(device): letterbox bars + all UI windows.
    inline uintptr_t cUI_Manager_render{};              // ENG 00758ED0

    // Language. WinMain (0x817B30) sets g_language from settings.cfg's LANGUAGE (exact match with a code, else it
    // stays DE) or a code in lower case on the command line, formats ".\SCRIPTS\<code>\global.res" and passes it to
    // cTextTable_load, which ignores it in these builds: it loads the text from the exe's BINARY resource 107 (each
    // uint16 XORed with the one before it, the first with 0x45AD) into a buffer from the game's operator new.
    inline uintptr_t g_language{};                      // ENG 017E7D34; int32, index into g_languageCodes
    inline uintptr_t g_languageCodes{};                 // ENG 00899394; char[16] each: US DE FR SP IT PL HU JP VC RU CZ
    constexpr int languageCount = 11;
    inline uintptr_t cTextTable_load{};                 // ENG 0080E680; thiscall (path) -> bool, this = g_textTable
    inline uintptr_t textTableAllocCall{};              // ENG 0080E6F0; its `call operator new` (cdecl (size))
    // Speech and sound effects: cMSS's constructor (only called by the instance getter 0x6770E0, on first use) opens
    // g_soundPakPath once and keeps the FILE*. initApp copies ".\PAK\SOUND.PAK" there (cMSS_setPakPath 0x677160)
    // and creates cMSS, but the startup movies (0x6A16E0, called from initApp before that) can create it first,
    // with the buffer's initial ".\PAK\SOUND.PAK".
    inline uintptr_t cMSS_ctor{};                       // ENG 00676200; thiscall (44100, 16, 1)
    inline uintptr_t g_soundPakPath{};                  // ENG 009D760C; char[256]
